export enum ArtifactGenerationStatus {
  /** The agent run producing this artifact has completed */
  Finalized = 'FINALIZED',
  /** No generation activity in flight */
  Idle = 'IDLE',
  /** The artifact is being generated (create/update in flight) */
  InProgress = 'IN_PROGRESS'
}

