/** Lifecycle status of an async board export job. Polling clients should treat COMPLETED, FAILED, and CANCELLED as terminal. */
export enum ExportJobStatus {
  /** The export was cancelled. */
  Cancelled = 'CANCELLED',
  /** The export finished successfully. download_url will be populated. */
  Completed = 'COMPLETED',
  /** The export failed. failure_reason and (when available) failure_message will be populated. */
  Failed = 'FAILED',
  /** The export is in progress. */
  Running = 'RUNNING'
}

/** Status of an async board export job, including download URL when completed. */
export type ExportJobStatusInfo = {
  __typename?: 'ExportJobStatusInfo';
  /** Presigned S3 download URL, available only when the job completed successfully and the URL has not yet expired. Returns null once expired — re-trigger the export to get a new one. */
  download_url?: Maybe<Scalars['String']['output']>;
  /** Human-readable error detail. Populated only when the job failed and the reason exposes safe text. */
  failure_message?: Maybe<Scalars['String']['output']>;
  /** Structured reason for failure. Populated only when the job failed. */
  failure_reason?: Maybe<ExportFailureReason>;
  /** Current job status. Terminal values: COMPLETED, FAILED, CANCELLED. */
  status?: Maybe<ExportJobStatus>;
};

/** Response from exporting document content as markdown. Contains the generated markdown text or error details. */
export type ExportMarkdownResult = {
  __typename?: 'ExportMarkdownResult';
  /** Detailed error message if the export failed. Check this when success is false. */
  error?: Maybe<Scalars['String']['output']>;
  /** The exported markdown content as a string. Ready to use in other systems or save to files. */
  markdown?: Maybe<Scalars['String']['output']>;
  /** True if document content was successfully exported as markdown */
  success: Scalars['Boolean']['output'];
};

/** Options for board export */
export type ExportOptionsInput = {
  /** Output format for connected items (Connect Boards) column values in CSV exports. NAME (the default) uses the linked items' display names; ID uses their IDs instead. Ignored for non-CSV formats. */
  connected_item_column_format?: InputMaybe<ConnectedItemColumnFormat>;
  /** Header row format for CSV exports. Ignored for other formats. */
  header_row?: InputMaybe<HeaderFormat>;
  /** Include item_id (and parent_item_id when subitems are enabled) columns at the end of CSV exports. */
  include_item_identifiers?: InputMaybe<Scalars['Boolean']['input']>;
  /** Include subitems in the export */
  include_subitems?: InputMaybe<Scalars['Boolean']['input']>;
  /** Include updates/comments in the export. Requires export_format: XLSX. */
  include_updates?: InputMaybe<Scalars['Boolean']['input']>;
  /** Behavior for columns with no codec support in CSV exports. Ignored for other formats. */
  non_importable_columns?: InputMaybe<NonImportableColumns>;
  /** Output format for people column values in CSV exports. When set to NAME, display names are used instead of IDs (e.g. "Alice Smith" instead of "user:123"). Ignored for non-CSV formats. */
  people_column_format?: InputMaybe<PeopleColumnFormat>;
};

/** Result of create_board_export. Either a completed synchronous export (ExportFile) or a started async job (ExportAsyncJob). The server chooses which branch to return; callers MUST handle both. Use ... on ExportFile { download_url } and ... on ExportAsyncJob { job_id }. */
